<script setup>
import {ref,watch} from 'vue';const privateNote=ref('');const props=defineProps({step:Object,timing:Object,elapsed:Number,index:Number,state:String,skipped:Array});watch(()=>props.index,()=>privateNote.value='');defineEmits(['next','skip','pause','resume','stop','home']);</script>
<template><section class="exercise card grounding" :data-state="state" :data-elapsed-ms="elapsed" :data-step="index" :data-entry-ms="timing?.entry" :data-first-instruction-frame-ms="timing?.firstFrame" :data-final-instruction-frame-ms="timing?.finalFrame" :data-guided-frame-duration-ms="timing?.finalFrame&&timing?.firstFrame ? timing.finalFrame-timing.firstFrame : null"><div class="section-top"><span class="eyebrow">Sensory grounding</span><span class="fine">{{Math.min(index+1,5)}} of 5</span></div><div class="sense-mark" aria-hidden="true">{{state==='completed'?'✓':step?.icon}}</div><h2 aria-live="polite">{{state==='paused'?'Take your time.':state==='completed'?'A moment, noticed.':state==='stopped'?'Stopped.':step?.text}}</h2><p class="instruction">{{state==='completed'?(skipped.length?'Finished with some senses skipped. You chose your own pace.':'The five senses are complete. Choose what comes next.') : state==='paused'?'Paused. Nothing advances until you choose.':state==='stopped'?'There is no need to finish.':'Identify them privately. You do not need to type anything.'}}</p><label v-if="state==='active'" class="private-note">Optional note, just for this step<textarea v-model="privateNote" maxlength="500" rows="2" placeholder="You can leave this blank." /></label><div v-if="state==='active'" class="grounding-actions"><button class="primary" @click="$emit('next')">{{index===4?'Finish':'Next sense'}} <span aria-hidden="true">→</span></button><button class="text-button" @click="$emit('skip')">Skip this sense</button></div><div class="sense-dots" aria-hidden="true"><span v-for="n in 5" :key="n" :class="{current:n===index+1,done:n<=index}"></span></div><div class="exercise-controls"><button v-if="state==='active'" class="secondary" @click="$emit('pause')">Pause</button><button v-if="state==='paused'" class="primary" @click="$emit('resume')">Resume</button><button v-if="['active','paused'].includes(state)" class="text-button" @click="$emit('stop')">Stop exercise</button><button v-else class="secondary" @click="$emit('home')">Return home</button></div><p class="fine">About one minute at 12 seconds per sense. Take longer if you choose.</p></section></template>
